-- 0016_results_account_seq.sql — an ADDITIVE per-account results cursor
-- (ledger item E1 / W6b; cloud-intelligence divergence remediation plan
-- 2026-09-01 §3 "W6 → W6b").
--
-- Why. analysis_results.seq is a GLOBAL identity sequence (GENERATED BY DEFAULT
-- AS IDENTITY, migration 0002). It is the pull cursor GET /v1/results?after=
-- advances on. Because the sequence is global across every tenant, an account
-- can observe how far the cursor jumps between two of its OWN results and infer
-- the total cross-tenant volume produced in between — a coarse side-channel
-- (E1). The fix is a per-account sequence: account A's account_seq is 1,2,3…
-- regardless of how many results any other account produced in the gaps, so it
-- leaks nothing about global volume.
--
-- ADDITIVE + DUAL-READ, never a cutover. The global `seq` column and the
-- `analysis_results_cursor` index STAY: in-flight nodes still pass a bare
-- decimal `after` and get the legacy global-seq path. The handler dual-reads —
-- bare decimal = legacy global path, `v2:<n>` = the new account-seq path — and
-- the wire carries BOTH `cursor` (legacy int64) and `account_cursor` (the new
-- string). The global cursor is retired one release later, NOT here.
--
-- ---------------------------------------------------------------------------
-- account_seq column + backfill.
-- ---------------------------------------------------------------------------
-- Added nullable so the backfill can populate it before the NOT NULL is set.
ALTER TABLE analysis_results ADD COLUMN account_seq bigint;

-- Serialize the backfill against concurrent result INSERTs. The whole lineage
-- runs inside one transaction (internal/cloudserver/db/db.go::migrateOnce), and
-- the ADD COLUMN above already holds ACCESS EXCLUSIVE on the table for the rest
-- of that transaction, so this LOCK is a belt-and-suspenders that documents the
-- intent and stays correct even if a future runner applied files
-- autocommit-per-statement. SHARE ROW EXCLUSIVE conflicts with the ROW
-- EXCLUSIVE lock every INSERT/UPDATE/DELETE takes, so no result row can be
-- inserted (and slip in with a NULL account_seq) between the backfill and the
-- SET NOT NULL below.
LOCK TABLE analysis_results IN SHARE ROW EXCLUSIVE MODE;

-- Assign each account a dense 1..N sequence ordered by the existing global seq,
-- independently per account. row_number() over the per-account partition is the
-- same monotone order the account already observed through the global cursor.
WITH ranked AS (
    SELECT id,
           row_number() OVER (PARTITION BY account_id ORDER BY seq) AS rn
      FROM analysis_results
)
UPDATE analysis_results r
   SET account_seq = ranked.rn
  FROM ranked
 WHERE r.id = ranked.id;

ALTER TABLE analysis_results ALTER COLUMN account_seq SET NOT NULL;

-- The uniqueness backstop for the allocator (MAX(account_seq)+1 under a
-- per-account advisory lock in CompleteJobWithResult): two completions for the
-- same account can never mint the same account_seq. Its btree index on
-- (account_id, account_seq) ALSO serves the cursor read
-- `WHERE account_id = ? AND account_seq > ? ORDER BY account_seq`, so no
-- separate index is created.
ALTER TABLE analysis_results
    ADD CONSTRAINT analysis_results_account_seq_uniq UNIQUE (account_id, account_seq);

-- No new role grants: sbci_api already holds SELECT/UPDATE and sbci_worker
-- SELECT/INSERT on analysis_results (migration 0015). A new column and
-- constraint on an already-granted table need no additional privilege.
